## Inputs

```
export type AreaTabsComponentInputs = {
  /**
   * Index des aktiven Tabs. Two-Way (`[(active)]`).
   *
   * @default 0
   */
  active?: number; // two-way: [(active)]
  /**
   * Zugänglicher Name der Tab-Leiste (WAI-ARIA verlangt aria-label/-labelledby).
   *
   * @default Bereiche
   */
  ariaLabel?: string;
}
```

## Outputs

```
export type AreaTabsComponentOutputs = {
  /** Index des aktiven Tabs. Two-Way (`[(active)]`). */
  activeChange: (e: number) => void;
}
```
